# Set up a folder for Presets
preset_dir = os.path.join(bpy.utils.user_resource("CONFIG"), "TP3D-presets")

# Named "Defaults" a generator page saves and loads (e.g. the Backplate
# Generator's) -- one JSON file per page, see picker_server.py's
# /get_page_defaults & /save_page_defaults. Created on first save. A
# subfolder, so the main panel's CSV presets in preset_dir never list them.
generator_defaults_dir = os.path.join(preset_dir, "generator_defaults")

# User-wide color styles, one JSON file per style. Created on first save.
color_style_dir = os.path.join(bpy.utils.user_resource("CONFIG"), "TrailPrint3D", "color_styles")

# Last-used settings per generator, carried over into the next Blender session --
# one JSON file each, see utils.ui_state.save_generator_settings. Created on first save.
generator_settings_dir = os.path.join(
    bpy.utils.user_resource("CONFIG"), "TrailPrint3D", "generator_settings"
)

# Set up a folder for the picker pages' (puzzleGenerator.html etc.) per-
# generator generation history -- one JSON file per page, see
# picker_server.py's /save_history_entry & /get_history.
generation_history_dir = os.path.join(bpy.utils.user_resource("CONFIG"), "TP3D-history")

# Real top-down Blender renders of past generations (export.save_history_thumbnail),
# named <history entry id>.png -- served by picker_server.py's
# /get_history_render once the generation that created them has actually
# finished, which is usually well after that picker session's own server
# already shut down.
generation_history_thumbnails_dir = os.path.join(generation_history_dir, "thumbnails")

# Which picker-page tutorials (assets/tutorial.js) the user has completed --
# a JSON object of {tutorial id: true}, see picker_server.py's
# /get_tutorial_progress & /complete_tutorial. Kept here rather than in the
# browser's own storage because each picker window gets a fresh, throwaway
# browser profile.
tutorial_progress_path = os.path.join(
    generation_history_dir, "tutorials_completed.json"
)

# Whether the user has permanently dismissed the in-generator 3MF addon promo
# popup -- shared across all generators (any one generator's "No thanks" sets
# this, so it never appears again on the others either).
threemf_promo_declined_path = os.path.join(
    generation_history_dir, "threemf_promo_declined.json"
)


def _ensure_dirs():
    """Create addon cache/preset directories. Call from register() only."""
    os.makedirs(cache_dir, exist_ok=True)
    os.makedirs(terrarium_cache_dir, exist_ok=True)
    os.makedirs(overpass_cache_dir, exist_ok=True)
    os.makedirs(elevation_results_dir, exist_ok=True)
    os.makedirs(satellite_cache_dir, exist_ok=True)
    os.makedirs(water_cache_dir, exist_ok=True)
    os.makedirs(preset_dir, exist_ok=True)
    os.makedirs(generation_history_dir, exist_ok=True)
    os.makedirs(generation_history_thumbnails_dir, exist_ok=True)


